def std(k,p,h): return f"<ul><li><strong>Pre koho:</strong> {k}</li><li><strong>Použitie:</strong> {p}</li><li><strong>Hlavné prínosy:</strong> {h}</li></ul>"
def li(*a): return "<ul>"+"".join(f"<li>{x}</li>" for x in a)+"</ul>"
