add("GVS-255385","Dr. Althea Vitamin C Boosting Serum – Rozjasňujúce pleťové sérum s vitamínom C – 30 ml","<p>Rozjasňujúce sérum Dr.Althea pre pleť s pigmentovými škvrnami, stopami po akné a nevyrovnaným tónom. Šesťdesiattri percent vody z rakytníka (Hippophae Rhamnoides) dopĺňa 5 % niacínamidu a 2 % kyseliny tranexámovej. Sérum je určené na dennú starostlivosť, nemá umelé farbivo ani parfumáciu a hydratuje, takže je vhodné aj pre tých, ktorým pripadajú klasické rozjasňujúce séra príliš agresívne.</p>"+li("objem 30 ml, sklenená fľaštička s pipetou","starostlivosť o škvrny, matný vzhľad a nerovnomerný tón pleti","bez umelého farbiva a parfumácie")+"<p>Pri pravidelnom používaní pleť pôsobí jasnejšie a vyrovnanejšie.</p>")
add("GVS-10933","CP-1 Head Spa Scalp Scaler – Peeling na pokožku hlavy – 210 ml","<p>Peelingový prípravok na pokožku hlavy z rady Head Spa značky CP-1 (Esthetic House). Dôkladne, ale šetrne čistí od nečistôt a odlupuje odumreté čiastočky pokožky. Obsahuje morskú soľ, kyselinu glykolovú a jemné tenzidy rastlinného pôvodu, ako aj mentol a extrakt z mäty piepornej, ktoré príjemne chladia a dávajú pocit sviežosti a čistoty.</p>"+li("objem 210 ml","hĺbkové čistenie a jemný peeling pokožky hlavy","chladivý pocit vďaka mentolu")+"<p>Spôsob použitia nájdete na obale produktu.</p>")
add("SPV-0234601","Afnan 9 AM Dive darčeková sada unisex parfumovaná voda 100 ml + sprchový gél 150 ml + dezodorant v spreji 150 ml","<p>Afnan 9 AM Dive je darčeková sada s parfumovanou vodou 100 ml a sprchovým gélom 150 ml. Svieža drevitá vôňa pre mužov aj ženy: citrón s mätou a navzdory sladkokyslej čiernej ríbezli.</p><ul><li><strong>Hlavné tóny:</strong> citrón, mäta, čierna ríbezľa, drevité tóny</li><li><strong>Kedy ju nosiť:</strong> ako darček, na jar a leto, na každý deň</li><li><strong>Charakter:</strong> svieža, drevitá a energická</li></ul>")
add("SPV-0230085","Armaf Club De Nuit Private Key To My Soul Extrait de Parfum U 100ml","<p>Armaf Club De Nuit Private Key To My Soul je unisex extrait de parfum (100 ml) z obľúbenej rady Club de Nuit od značky Armaf. Vyššia koncentrácia vône zaručuje intenzívnu stopu a dlhú výdrž.</p><ul><li><strong>Kedy ju nosiť:</strong> na večer, na jeseň a v zime, na zvláštne príležitosti</li><li><strong>Charakter:</strong> sýta, intenzívna a dlhotrvajúca</li></ul>")
add("SPV-0247797","Armaf Club De Nuit Blue Iconic SET M (EDP 105ml + BS 200ml)","<p>Club de Nuit Blue Iconic je darčeková sada pre mužov: parfumovaná voda 105 ml a telový sprej 200 ml od Armaf. Fougèrová ambrovo-drevitá vôňa s citrusovým začiatkom, príjemná na každý deň.</p><ul><li><strong>Hlavné tóny:</strong> grapefruit, citrón, mäta, ružové korenie, drevité tóny</li><li><strong>Kedy ju nosiť:</strong> ako darček, na každý deň</li><li><strong>Charakter:</strong> svieža, čistá a drevitá</li></ul>")
add("SPV-0234597","Afnan Supremacy Silver darčeková sada pre mužov parfumovaná voda 100 ml + sprchový gél 100 ml + balzam po holení 100 ml","<p>Supremacy Silver od Afnan je darčeková sada pre mužov: parfumovaná voda 100 ml a sprchový gél. Intenzívna, zmyselná a svieža vôňa, ktorá vydrží celý deň, ale neprebije okolie.</p><ul><li><strong>Hlavné tóny:</strong> sviežé tóny</li><li><strong>Kedy ju nosiť:</strong> ako darček, na každý deň, na večer</li><li><strong>Charakter:</strong> svieža, zmyselná a trvanlivá</li></ul>")
add("SPV-0234603","Afnan 9 PM Pour Femme EDP 100 ml + sprchový gél 100 ml + telový závoj 150 ml + telové mlieko 100 ml","<p>Afnan 9pm Pour Femme je darčeková sada pre ženy: parfumovaná voda 100 ml, sprchový gél, telové mlieko a telový mist. Zmyselná, sladká a hravá vôňa otvorená ovocnými tónmi.</p><ul><li><strong>Hlavné tóny:</strong> malina, jablko, pomaranč, fialka</li><li><strong>Kedy ju nosiť:</strong> ako darček, na večer</li><li><strong>Charakter:</strong> sladká, ovocná a zmyselná</li></ul>")
add("SPV-0218629","Nuxe Prodigieux Floral Le Parfum EDP W 50ml","<p>Prodigieux Floral Le Parfum od Nuxe je dámska parfumovaná voda s povzbudzujúcou kvetinovou vôňou: sviežie citrusové tóny kalábrijského bergamotu a citróna sa spájajú s kvetmi.</p><ul><li><strong>Hlavné tóny:</strong> bergamot, citrón, kvety</li><li><strong>Kedy ju nosiť:</strong> na každý deň, na jar a leto</li><li><strong>Charakter:</strong> svieža, kvetinová a povzbudzujúca</li></ul>")
