add("GVS-255736","Dr. Althea Jelly Seal Dewy Mask – Hydratačná gélová maska","<p>Dvojvrstvová gélová maska Dr.Althea Jelly Seal Dewy obnovuje hydratáciu a lipidovú rovnováhu pleti. Obsahuje komplex 10 typov kyseliny hyalurónovej, rastlinnú PDRN z listov lotosu a panthenol s madecassosidom. Je vhodná pre citlivú a zmiešanú pleť a dáva jej vláčny, sviežy vzhľad.</p>"+li("10 typov kyseliny hyalurónovej","rastlinná PDRN z lotosu","pre citlivú a zmiešanú pleť"))
add("GVS-541881","CP-1 Keratin Concentrate Ampoule – Keratínová esencia na vlasy – vzorka 10 ml","<p>Koncentrovaná keratínová esencia CP-1 pre suché, lámavé a krepovité vlasy. Pomáha udržať správnu hladinu vlhkosti, vracia vlasom pružnosť a lesk, opravuje poškodené miesta a predchádza rozstrapkaným končekom. Ľahká textúra pripomína odtučnený olej, takže vlasy nezaťažuje. Obsahuje keratín, extrakt z listov baobabu a elastín a je bez sulfátov.</p>"+li("objem 10 ml","esencia pre suché, lámavé a krepovité vlasy","bez sulfátov"))
add("GVS-11251","CP-1 Premium Hair Treatment – Proteínová maska na vlasy – 250 ml","<p>Proteínová maska CP-1 Premium Hair Treatment pre namáhané vlasy: suché, lámavé, odfarbené aj poškodené teplom či chémiou. Hodvábny proteín a ceramidy pomáhajú vlasy vyplniť zvnútra a spevniť rozstrapkané končeky, komplex s mandľovým a arganovým olejom ich zjemňuje a dodáva im lesk. Hodí sa na domácu starostlivosť aj do salónu.</p>"+li("objem 250 ml","hodvábny proteín, ceramidy, mandľový a arganový olej","pre suché, farbené a tepelne namáhané vlasy"))
add("GVS-10551","CP-1 Premium Hair Treatment – Proteínová maska na vlasy – 25 ml","<p>Proteínová maska CP-1 Premium Hair Treatment pre namáhané vlasy: suché, lámavé, odfarbené aj poškodené teplom či chémiou. Hodvábny proteín a ceramidy pomáhajú vlasy vyplniť zvnútra a spevniť rozstrapkané končeky, komplex s mandľovým a arganovým olejom ich zjemňuje a dodáva im lesk. Hodí sa na domácu starostlivosť aj do salónu.</p>"+li("objem 25 ml","hodvábny proteín, ceramidy, mandľový a arganový olej","pre suché, farbené a tepelne namáhané vlasy"))
add("GVS-11848","CP-1 3 Seconds Hair Fill-Up Ampoule – Regeneračná vlasová ampulka – 170 ml","<p>Vlasová ampulka CP-1 3 Seconds Hair Fill-Up je sérum-maska na okamžitú obnovu. Uzatvára poškodenú kutikulu, vypĺňa nerovnosti na vlasoch a vyhladzuje štruktúru, takže vlasy pôsobia hebkejšie a pružnejšie. Obsahuje panthenol, hydrolyzovaný hodváb a elastín proti lámavosti.</p>"+li("objem 170 ml","regeneračná starostlivosť pre poškodené vlasy","panthenol, hydrolyzovaný hodváb, elastín"))
add("GVS-12081","CP-1 Bright Complex Intense Nourishing Shampoo 2.0 – Vyživujúci šampón s proteínmi a kolagénom – 500 ml","<p>Intenzívne vyživujúci šampón CP-1 Bright Complex (verzia 2.0) s proteínmi a kolagénom. Čistí pokožku hlavy a vlasy od nadbytočného mazu a nečistôt, ale nevysúša ich. Proteíny vracajú vlasom pružnosť a lesk a zmierňujú lámavosť, jojobový, kaméliový a kokosový olej ich chráni. Vhodný pre všetky typy vlasov a denné použitie.</p>"+li("objem 500 ml","vhodný pre všetky typy vlasov, aj na každodenné umývanie","proteíny, kolagén a rastlinné oleje"))
add("GVS-13675","CP-1 Aquaxyl Complex Intense Moisture Shampoo – Hydratačný šampón pre farbené vlasy – 100 ml","<p>Šampón CP-1 Aquaxyl Complex Intense Moisture šetrne čistí pokožku hlavy a hydratuje aj zjemňuje poškodené vlasy. Patentovaný komplex Aquaxyl™ zaisťuje hydratáciu vlasov vo viacerých vrstvách, šampón nevysúša ani citlivú pokožku hlavy a hodí sa pre farbené a odfarbené vlasy. Má pH 5,5 a obsahuje prírodné oleje, aminokyseliny, kolagén, hodváb a keratín.</p>"+li("objem 100 ml","pH 5,5","vhodný pre farbené a odfarbené vlasy"))
add("GVS-14849","CP-1 Keratin Intensive Fill-up Hair Mask – Keratínová maska na vlasy – 200 ml","<p>Proteínová regeneračná maska na vlasy CP-1 Keratin Intensive Fill-up od Esthetic House. Je určená pre vlasy namáhané farbením a tepelným stylingom. Keratín vyhladzuje kutikulu, patentovaný komplex Aquarich (extrakt z čierneho ovsa s lecitínom) tvorí ochrannú bariéru proti vysušeniu a hydrolyzovaný kolagén s proteínmi vlasy spevňujú a dodávajú im lesk. Maska vonia sladko kvetinovo.</p>"+li("objem 200 ml","pre poškodené, farbené a krepovité vlasy","vyhladzuje, zjemňuje a obmedzuje trepenie končekov")+"<p>Aplikujte po umytí šampónom na vlhké vlasy, nechajte krátko pôsobiť a opláchnite (pozri návod na obale).</p>")
